window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-94da8cb5bd5c8e02"]={"versions": [{"id": "FIG-94da8cb5bd5c8e02", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (Strukturmodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release R2.1.20, Dokument <em>AUTOSAR_InteractionBehavioralModels</em>, Kapitel 4.2.5 <em>Datatypes</em>).</li>\n<li><strong>Funktionaler Zweck:</strong> Formale Definition des Datentypsystems für die Verhaltensmodellierung (<em>Behavior Modeling Tools</em>, BMT) von Software-Components. Es definiert die Metaklassen zur Spezifikation elementarer, semantisch annotierter sowie zusammengesetzter Datentypen, die als Basis für Schnittstellen (Ports, Sender-Receiver-, Client-Server-Interfaces) und interne Zustandsvariablen dienen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>ARElement</code>:</strong> Oberste abstrakte Wurzel für alle autarken, paketierbaren AUTOSAR-Modellelemente (in ARXML serialisierbar).</li>\n<li><strong><code>Datatypes::Datatype</code>:</strong> Spezialisiert <code>ARElement</code>. Abstrakter Basistyp für alle Datentypdefinitionen im System.</li>\n<li><strong><code>Datatypes::PrimitiveType</code>:</strong> Abstrakte Generalisierung atomarer Basistypen.</li>\n<li><strong><code>Datatypes::BooleanType</code>:</strong> Wahrheitswert (<code>TRUE</code>/<code>FALSE</code>).</li>\n<li><strong><code>Datatypes::StringType</code>:</strong> Zeichenketten.</li>\n<li><strong><code>Datatypes::CharType</code>:</strong> Einzelzeichen.</li>\n<li><strong><code>Datatypes::IntegerType</code>:</strong> Ganzzahltypen; annotiert mit dem Stereotyp/Constraint <code>«Range»</code> zur Spezifikation von Minimal- und Maximalwerten.</li>\n<li><strong><code>Datatypes::RealType</code>:</strong> Fließkommatypen (IEEE 754); annotiert mit dem Stereotyp/Constraint <code>«Range»</code>.</li>\n<li><strong><code>Datatypes::OpaqueType</code>:</strong> Typ-agnostische rohe Datenblöcke/Byte-Arrays ohne interne semantische Interpretation durch das Metamodell.</li>\n<li><strong><code>Datatypes::PrimitiveTypeWithSemantics</code>:</strong> Spezialisiert <code>Datatype</code>. Ermöglicht die semantische Anreicherung eines primitiven Basistyps (z. B. physikalische Einheit, Skalierung, Quantisierung).</li>\n<li><strong><code>Datatypes::CompositeType</code>:</strong> Abstrakte Basisklasse für zusammengesetzte Datentypen.</li>\n<li><strong><code>Datatypes::RecordType</code>:</strong> Strukturierter Datentyp aus heterogenen Elementen (Äquivalent zu C-<code>struct</code>).</li>\n<li><strong><code>Datatypes::ArrayType</code>:</strong> Homogener Datentyp fester oder variabler Dimensionierung (Äquivalent zu C-Array).</li>\n<li><strong>Paket <code>BM Software-Component</code> (aus <code>Behavior Modeling</code>):</strong> Kontext der Verhaltensmodellierung, der über <code>«import»</code>-Abhängigkeiten auf das Typsystem zugreift.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Vererbung (<code>Generalization</code>):</strong></li>\n<li><code>Datatype</code> erbt von <code>ARElement</code>.</li>\n<li><code>PrimitiveType</code>, <code>PrimitiveTypeWithSemantics</code> und <code>CompositeType</code> erben von <code>Datatype</code>.</li>\n<li><code>BooleanType</code>, <code>StringType</code>, <code>CharType</code>, <code>IntegerType</code>, <code>RealType</code> und <code>OpaqueType</code> erben von <code>PrimitiveType</code>.</li>\n<li><code>RecordType</code> und <code>ArrayType</code> erben von <code>CompositeType</code>.</li>\n<li><strong>Assoziationen:</strong></li>\n<li><code>PrimitiveTypeWithSemantics</code> <code>0..*</code> $\\rightarrow$ <code>1</code> <code>PrimitiveType</code> (Rollenname: <code>+type</code>): Ein semantischer Typ referenziert zwingend genau einen konkreten primitiven Basistyp. Ein primitiver Basistyp kann von beliebig vielen semantischen Typen wiederverwendet werden.</li>\n<li><code>CompositeType</code> $\\rightarrow$ <code>Datatype</code> (Rollenname: <code>+elementType</code>, Kardinalität <code>1</code>): Assoziation zur Definition des referenzierten Elementtyps für die Aggregation.</li>\n<li><strong>Abhängigkeiten (<code>«import»</code>):</strong></li>\n<li><code>BM Software-Component</code> importiert direkt: <code>Datatype</code>, <code>PrimitiveType</code>, <code>PrimitiveTypeWithSemantics</code>, <code>BooleanType</code>, <code>IntegerType</code> und <code>RealType</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm bildet keine Laufzeit-Abläufe, Task-Zyklen oder Interaktions-Sequenzen ab.</li>\n<li><strong>Entwurfs- und Generierungszeit-Verhalten:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modellerstellung (Designtime):</strong> BMT-Werkzeuge instanziieren die spezialisierten Klassen zur Typdefinition in der SWC-Beschreibung.</li>\n<li><strong>Metamodell-Transformation:</strong> Codegeneratoren (z. B. RTE-Generator, Contract Phase) werten die Spezialisierungen aus und mappen sie auf die C-Typen der Plattform (<code>Platform_Types.h</code> wie <code>uint8</code>, <code>sint16</code>, <code>float32</code>, <code>boolean</code> bzw. <code>Rte_Type.h</code>).</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Historischer Metamodell-Stand (R2.1 vs. R4.x):</strong></li>\n<li>Das dargestellte Schema repräsentiert das frühe AUTOSAR-Typsystem (R2.1). In modernen Releases (ab R4.0) wurde diese Struktur durch die strikte Trennung von <code>ApplicationDataType</code> (physikalische Sicht/Semantik), <code>ImplementationDataType</code> (C-Codegenerierung/Speicherlayout) und <code>BaseType</code> ersetzt.</li>\n<li><strong>Code-Generierung & C-Mapping:</strong></li>\n<li><code>RecordType</code> führt in <code>Rte_Type.h</code> zur Generierung von <code>typedef struct { ... }</code>.</li>\n<li><code>ArrayType</code> generiert fixe C-Arrays mit definierten Indexgrenzen.</li>\n<li><code>OpaqueType</code> erfordert hardwarenahe Pufferbehandlung (typischerweise <code>uint8[]</code> bzw. <code>void*</code>-Puffer im Speicher).</li>\n<li><strong>Wertebereichsüberwachung (<code>Range</code>):</strong></li>\n<li>Entwickler von SWC-Verhaltensmodellen und Generatoren müssen die Constraints auf <code>IntegerType</code> und <code>RealType</code> berücksichtigen; Grenzwertverletzungen müssen bereits in der Entwurfsphase durch Modellprüfungen oder zur Laufzeit durch Rättigung/Defensive Programming in den Runnables abgefangen werden.</li>\n</ul>"}, {"id": "FIG-8152a2f12403c841", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Metamodell-Klassendiagramm (Strukturmodell).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Classic Platform (Release R2.1.20, Dokument <em>AUTOSAR_InteractionBehavioralModels</em>, Kapitel 4.2.5 <em>Datatypes</em>).</li>\n<li><strong>Funktionaler Zweck:</strong> Formale Definition des Datentypsystems für die Verhaltensmodellierung (<em>Behavior Modeling Tools</em>, BMT) von Software-Components. Es definiert die Metaklassen zur Spezifikation elementarer, semantisch annotierter sowie zusammengesetzter Datentypen, die als Basis für Schnittstellen (Ports, Sender-Receiver-, Client-Server-Interfaces) und interne Zustandsvariablen dienen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Metaklassen & Stereotypen</p>\n<ul class=\"fig-list\">\n<li><strong><code>ARElement</code>:</strong> Oberste abstrakte Wurzel für alle autarken, paketierbaren AUTOSAR-Modellelemente (in ARXML serialisierbar).</li>\n<li><strong><code>Datatypes::Datatype</code>:</strong> Spezialisiert <code>ARElement</code>. Abstrakter Basistyp für alle Datentypdefinitionen im System.</li>\n<li><strong><code>Datatypes::PrimitiveType</code>:</strong> Abstrakte Generalisierung atomarer Basistypen.</li>\n<li><strong><code>Datatypes::BooleanType</code>:</strong> Wahrheitswert (<code>TRUE</code>/<code>FALSE</code>).</li>\n<li><strong><code>Datatypes::StringType</code>:</strong> Zeichenketten.</li>\n<li><strong><code>Datatypes::CharType</code>:</strong> Einzelzeichen.</li>\n<li><strong><code>Datatypes::IntegerType</code>:</strong> Ganzzahltypen; annotiert mit dem Stereotyp/Constraint <code>«Range»</code> zur Spezifikation von Minimal- und Maximalwerten.</li>\n<li><strong><code>Datatypes::RealType</code>:</strong> Fließkommatypen (IEEE 754); annotiert mit dem Stereotyp/Constraint <code>«Range»</code>.</li>\n<li><strong><code>Datatypes::OpaqueType</code>:</strong> Typ-agnostische rohe Datenblöcke/Byte-Arrays ohne interne semantische Interpretation durch das Metamodell.</li>\n<li><strong><code>Datatypes::PrimitiveTypeWithSemantics</code>:</strong> Spezialisiert <code>Datatype</code>. Ermöglicht die semantische Anreicherung eines primitiven Basistyps (z. B. physikalische Einheit, Skalierung, Quantisierung).</li>\n<li><strong><code>Datatypes::CompositeType</code>:</strong> Abstrakte Basisklasse für zusammengesetzte Datentypen.</li>\n<li><strong><code>Datatypes::RecordType</code>:</strong> Strukturierter Datentyp aus heterogenen Elementen (Äquivalent zu C-<code>struct</code>).</li>\n<li><strong><code>Datatypes::ArrayType</code>:</strong> Homogener Datentyp fester oder variabler Dimensionierung (Äquivalent zu C-Array).</li>\n<li><strong>Paket <code>BM Software-Component</code> (aus <code>Behavior Modeling</code>):</strong> Kontext der Verhaltensmodellierung, der über <code>«import»</code>-Abhängigkeiten auf das Typsystem zugreift.</li>\n</ul>\n<p class=\"fig-p\">#### Relationen & Kardinalitäten</p>\n<ul class=\"fig-list\">\n<li><strong>Vererbung (<code>Generalization</code>):</strong></li>\n<li><code>Datatype</code> erbt von <code>ARElement</code>.</li>\n<li><code>PrimitiveType</code>, <code>PrimitiveTypeWithSemantics</code> und <code>CompositeType</code> erben von <code>Datatype</code>.</li>\n<li><code>BooleanType</code>, <code>StringType</code>, <code>CharType</code>, <code>IntegerType</code>, <code>RealType</code> und <code>OpaqueType</code> erben von <code>PrimitiveType</code>.</li>\n<li><code>RecordType</code> und <code>ArrayType</code> erben von <code>CompositeType</code>.</li>\n<li><strong>Assoziationen:</strong></li>\n<li><code>PrimitiveTypeWithSemantics</code> <code>0..*</code> $\\rightarrow$ <code>1</code> <code>PrimitiveType</code> (Rollenname: <code>+type</code>): Ein semantischer Typ referenziert zwingend genau einen konkreten primitiven Basistyp. Ein primitiver Basistyp kann von beliebig vielen semantischen Typen wiederverwendet werden.</li>\n<li><code>CompositeType</code> $\\rightarrow$ <code>Datatype</code> (Rollenname: <code>+elementType</code>, Kardinalität <code>1</code>): Assoziation zur Definition des referenzierten Elementtyps für die Aggregation.</li>\n<li><strong>Abhängigkeiten (<code>«import»</code>):</strong></li>\n<li><code>BM Software-Component</code> importiert direkt: <code>Datatype</code>, <code>PrimitiveType</code>, <code>PrimitiveTypeWithSemantics</code>, <code>BooleanType</code>, <code>IntegerType</code> und <code>RealType</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Nicht zutreffend (rein statisches Metamodell):</strong> Das Diagramm bildet keine Laufzeit-Abläufe, Task-Zyklen oder Interaktions-Sequenzen ab.</li>\n<li><strong>Entwurfs- und Generierungszeit-Verhalten:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modellerstellung (Designtime):</strong> BMT-Werkzeuge instanziieren die spezialisierten Klassen zur Typdefinition in der SWC-Beschreibung.</li>\n<li><strong>Metamodell-Transformation:</strong> Codegeneratoren (z. B. RTE-Generator, Contract Phase) werten die Spezialisierungen aus und mappen sie auf die C-Typen der Plattform (<code>Platform_Types.h</code> wie <code>uint8</code>, <code>sint16</code>, <code>float32</code>, <code>boolean</code> bzw. <code>Rte_Type.h</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Historischer Metamodell-Stand (R2.1 vs. R4.x):</strong></li>\n<li>Das dargestellte Schema repräsentiert das frühe AUTOSAR-Typsystem (R2.1). In modernen Releases (ab R4.0) wurde diese Struktur durch die strikte Trennung von <code>ApplicationDataType</code> (physikalische Sicht/Semantik), <code>ImplementationDataType</code> (C-Codegenerierung/Speicherlayout) und <code>BaseType</code> ersetzt.</li>\n<li><strong>Code-Generierung & C-Mapping:</strong></li>\n<li><code>RecordType</code> führt in <code>Rte_Type.h</code> zur Generierung von <code>typedef struct { ... }</code>.</li>\n<li><code>ArrayType</code> generiert fixe C-Arrays mit definierten Indexgrenzen.</li>\n<li><code>OpaqueType</code> erfordert hardwarenahe Pufferbehandlung (typischerweise <code>uint8[]</code> bzw. <code>void*</code>-Puffer im Speicher).</li>\n<li><strong>Wertebereichsüberwachung (<code>Range</code>):</strong></li>\n<li>Entwickler von SWC-Verhaltensmodellen und Generatoren müssen die Constraints auf <code>IntegerType</code> und <code>RealType</code> berücksichtigen; Grenzwertverletzungen müssen bereits in der Entwurfsphase durch Modellprüfungen oder zur Laufzeit durch Rättigung/Defensive Programming in den Runnables abgefangen werden.</li>\n</ul>"}], "trans": [{"from": "FIG-94da8cb5bd5c8e02", "to": "FIG-8152a2f12403c841", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
